###### Introduction - Motivation - What the program does ###############################################################################################
#The purpose of this program is to study the group G of transformations of the cube that is generated by R and U^2. It turns out to have 14,400 elements.
#In it we consider the element a=R^2U^2R^2U^2R^2U^2 that has order 2. Its centralizer H, i.e. the subgroup consisting of all the elements of G that commute
#with a is a subgroup of order 1,440. We let G act on the coset space G/H by left multiplication and we isolate the kernel of the action K. The group K is
#a normal subgroup of G that has 120 elements. Incidentally, we get that G is not simple. We finally find the orders of the elements of K and we notice
#that they match the orders of the elements of the symmetric group S_5. By considering the action of K on its 5 Sylow subgroups, it is easy to see that K is
#actually isomorphic to S_5. The question that is left unanswered for the moment being is what the structure of the quotient G/K is. Note that it also has
#120 elements and one may ask whether it is isomorphic to S_5 too. If that is the case then G turns out to be an extension of S_5 by S_5.
#########################################################################################################################################################


#We begin by defining the 6 faces of the cube. The letters o,w,y,g,b,r correspond to the colors orange, white, yellow, green, blue and red.
#In other words, we consider that we are holding the cube so that the front face is orange, the top face is yellow and bottom face is white.

front=["o","o","o","o","o","o","o","o","o"]
bottom=["w","w","w","w","w","w","w","w","w"]
top=["y","y","y","y","y","y","y","y","y"]
left=["g","g","g","g","g","g","g","g","g"]
right=["b","b","b","b","b","b","b","b","b"]
back=["r","r","r","r","r","r","r","r","r"]



#The function establishInitialPosition() serves the purpose of bringing the cube to its initial position once transformations have been applied to them.


def establishInitialPosition():
  for i in range(9):
    front[i]="o"
    bottom[i]="w"
    top[i]="y"
    left[i]="g"
    right[i]="b"
    back[i]="r"

  return


#We next define the different simple face rotations of the cube. We can list them as follows:
# R is the rotation of the right face away from us - R' is the reverse rotation
# U is the rotation of the top face in the clockwise way - U' is the reverse rotation
# L is the rotation of the left face toward us - L' is the reverse rotation
# F is the rotation of the front face in the clockwise way - F is the reverse rotation
# D is the rotation of the bottom face in the counterclockwise way (as seen from above) - D' is the reverse rotation
# B is the rotation of the back face in the counterclockwise way (as seen from the front) - B' is the reverse rotation

#Here, it is important to identify the enumeration of all the faces. Let us start with the front face. In enumerating the front
#face, we begin with the top row from the left to the right and we proceed row by row. We mirror this enumeration for the back face.
#In enumerating the top face we begin with the back rwo from the left to the right and we proceed row by row. We mirror this enumeration
#for the bottom face. In enumerating the left face, we begin with the top rwo from the back to the front and we proceed row by row.
#Note that in all of the above descriptions, we hold the cube in the way that we described in the beginning.


### BEGINNING OF THE 12 transformation functions #############################


def executeD():
  store=front.copy()
  front[6]=left[6]
  front[7]=left[7]
  front[8]=left[8]
  left[6]=back[8]
  left[7]=back[7]
  left[8]=back[6]
  back[6]=right[6]
  back[7]=right[7]
  back[8]=right[8]
  right[6]=store[8]
  right[7]=store[7]
  right[8]=store[6]

 

  store=bottom.copy()
  bottom[6]=store[0]
  bottom[3]=store[1]
  bottom[0]=store[2]
  bottom[1]=store[5]
  bottom[2]=store[8]
  bottom[5]=store[7]
  bottom[8]=store[6]
  bottom[7]=store[3]
  return


def executeDprime():
  store=left.copy()
  left[6]=front[6]
  left[7]=front[7]
  left[8]=front[8]
  front[8]=right[6]
  front[7]=right[7]
  front[6]=right[8]
  right[6]=back[6]
  right[7]=back[7]
  right[8]=back[8]
  back[8]=store[6]
  back[7]=store[7]
  back[6]=store[8]


 

  store=bottom.copy()
  bottom[0]=store[6]
  bottom[1]=store[3]
  bottom[2]=store[0]
  bottom[5]=store[1]
  bottom[8]=store[2]
  bottom[7]=store[5]
  bottom[6]=store[8]
  bottom[3]=store[7]
  return


def executeB():
  store=left.copy()
  left[0]=top[2]
  left[3]=top[1]
  left[6]=top[0]
  top[0]=right[0]
  top[1]=right[3]
  top[2]=right[6]
  right[0]=bottom[2]
  right[3]=bottom[1]
  right[6]=bottom[0]
  bottom[0]=store[0]
  bottom[1]=store[3]
  bottom[2]=store[6]


  store=back.copy()
  back[6]=store[0]
  back[3]=store[1]
  back[0]=store[2]
  back[7]=store[3]
  back[8]=store[6]
  back[5]=store[7]
  back[2]=store[8]
  back[1]=store[5]
  return


def executeBprime():
  store=top.copy()
  top[2]=left[0]
  top[1]=left[3]
  top[0]=left[6]
  left[0]=bottom[0]
  left[3]=bottom[1]
  left[6]=bottom[2]
  bottom[2]=right[0]
  bottom[1]=right[3]
  bottom[0]=right[6]
  right[0]=store[0]
  right[3]=store[1]
  right[6]=store[2]




  store=back.copy()
  back[0]=store[6]
  back[1]=store[3]
  back[2]=store[0]
  back[3]=store[7]
  back[6]=store[8]
  back[7]=store[5]
  back[8]=store[2]
  back[5]=store[1]
  return


def executeF():
  store=top.copy()
  top[6]=left[8]
  top[7]=left[5]
  top[8]=left[2]
  left[2]=bottom[6]
  left[5]=bottom[7]
  left[8]=bottom[8]
  bottom[6]=right[8]
  bottom[7]=right[5]
  bottom[8]=right[2]
  right[2]=store[6]
  right[5]=store[7]
  right[8]=store[8]
  store=front.copy()
  front[0]=store[6]
  front[1]=store[3]
  front[2]=store[0]
  front[3]=store[7]
  front[6]=store[8]
  front[7]=store[5]
  front[8]=store[2]
  front[5]=store[1]
  return


def executeFprime():
  store=left.copy()
  left[8]=top[6]
  left[5]=top[7]
  left[2]=top[8]
  top[6]=right[2]
  top[7]=right[5]
  top[8]=right[8]
  right[8]=bottom[6]
  right[5]=bottom[7]
  right[2]=bottom[8]
  bottom[6]=store[2]
  bottom[7]=store[5]
  bottom[8]=store[8]


  store=front.copy()
  front[6]=store[0]
  front[3]=store[1]
  front[0]=store[2]
  front[7]=store[3]
  front[8]=store[6]
  front[5]=store[7]
  front[2]=store[8]
  front[1]=store[5]
  return

def executeL():
  store=front.copy()
  front[0]=top[0]
  front[3]=top[3]
  front[6]=top[6]
  top[0]=back[6]
  top[3]=back[3]
  top[6]=back[0]
  back[0]=bottom[0]
  back[3]=bottom[3]
  back[6]=bottom[6]
  bottom[0]=store[6]
  bottom[3]=store[3]
  bottom[6]=store[0]


  store=left.copy()
  left[2]=store[0]
  left[5]=store[1]
  left[8]=store[2]
  left[0]=store[6]
  left[1]=store[3]
  left[3]=store[7]
  left[6]=store[8]
  left[7]=store[5]
  return


def executeLprime():
  store=top.copy()
  top[0]=front[0]
  top[3]=front[3]
  top[6]=front[6]
  front[0]=bottom[6]
  front[3]=bottom[3]
  front[6]=bottom[0]
  bottom[0]=back[0]
  bottom[3]=back[3]
  bottom[6]=back[6]
  back[0]=store[6]
  back[3]=store[3]
  back[6]=store[0]
  store=left.copy()
  left[0]=store[2]
  left[1]=store[5]
  left[2]=store[8]
  left[6]=store[0]
  left[3]=store[1]
  left[7]=store[3]
  left[8]=store[6]
  left[5]=store[7]
  return



def executeR():
  store=top.copy()
  top[2]=front[2]
  top[5]=front[5]
  top[8]=front[8]
  front[2]=bottom[8]
  front[5]=bottom[5]
  front[8]=bottom[2]
  bottom[2]=back[2]
  bottom[5]=back[5]
  bottom[8]=back[8]
  back[2]=store[8]
  back[5]=store[5]
  back[8]=store[2]
  store=right.copy()
  right[0]=store[2]
  right[1]=store[5]
  right[2]=store[8]
  right[6]=store[0]
  right[3]=store[1]
  right[7]=store[3]
  right[8]=store[6]
  right[5]=store[7]
  return


def executeRprime():
  store=front.copy()
  front[2]=top[2]
  front[5]=top[5]
  front[8]=top[8]
  top[2]=back[8]
  top[5]=back[5]
  top[8]=back[2]
  back[2]=bottom[2]
  back[5]=bottom[5]
  back[8]=bottom[8]
  bottom[2]=store[8]
  bottom[5]=store[5]
  bottom[8]=store[2]


  store=right.copy()
  right[2]=store[0]
  right[5]=store[1]
  right[8]=store[2]
  right[0]=store[6]
  right[1]=store[3]
  right[3]=store[7]
  right[6]=store[8]
  right[7]=store[5]
  return

def executeU():
  store=left.copy()
  left[0]=front[0]
  left[1]=front[1]
  left[2]=front[2]
  front[0]=right[2]
  front[1]=right[1]
  front[2]=right[0]
  right[0]=back[0]
  right[1]=back[1]
  right[2]=back[2]
  back[2]=store[0]
  back[1]=store[1]
  back[0]=store[2]

  store=top.copy()
  top[0]=store[6]
  top[1]=store[3]
  top[2]=store[0]
  top[5]=store[1]
  top[8]=store[2]
  top[7]=store[5]
  top[6]=store[8]
  top[3]=store[7]
  return


def executeUprime():
  store=front.copy()
  front[0]=left[0]
  front[1]=left[1]
  front[2]=left[2]
  left[2]=back[0]
  left[1]=back[1]
  left[0]=back[2]
  back[0]=right[0]
  back[1]=right[1]
  back[2]=right[2]
  right[0]=store[2]
  right[1]=store[1]
  right[2]=store[0]

  store=top.copy()
  top[6]=store[0]
  top[3]=store[1]
  top[0]=store[2]
  top[1]=store[5]
  top[2]=store[8]
  top[5]=store[7]
  top[8]=store[6]
  top[7]=store[3]
  return


