#The following function  was used for diagnostic purposes and prints the given configuration of the cube

def printPosition():
  print(front)
  print(left)
  print(right)
  print(back)
  print(top)
  print(bottom)
  return
  
####################################################################################################################################




#The following function checks to see if the current cube configuration coincides with the initial configuration of the cube


def checkInitial():
  if front==["o","o","o","o","o","o","o","o","o"] and bottom==["w","w","w","w","w","w","w","w","w"] and top==["y","y","y","y","y","y","y","y","y"] and left==["g","g","g","g","g","g","g","g","g"] and right==["b","b","b","b","b","b","b","b","b"] and back==["r","r","r","r","r","r","r","r","r"]:
    return True
  else:
    return False


###################################################################################################################################




#The following function turns the current configuration into a word consisting of the letters o,w,y,g,b,r 9 times each where the front face appears first, then the left face, then the right face, then the back face,
#then the top face and finally the bottom face.

def positionToWord():
  word=""
  for i in range(9):
    word=word+front[i]
  for i in range(9):
    word=word+left[i]
  for i in range(9):
    word=word+right[i]
  for i in range(9):
    word=word+back[i]
  for i in range(9):
    word=word+top[i]
  for i in range(9):
    word=word+bottom[i]
  return word

##################################################################################################################################




#The following function configures the cube into a given position according to a given word of 54 letters that describe a configuration in the order that was indicated in the function positionToWord()

def wordToPosition(word):
  for i in range(9):
    front[i]=word[i]
  for i in range(9):
    left[i]=word[i+9]
  for i in range(9):
    right[i]=word[i+18]
  for i in range(9):
    back[i]=word[i+27]
  for i in range(9):
    top[i]=word[i+36]
  for i in range(9):
    bottom[i]=word[i+45]
  return

################################################################################################################################



#The following function computes the order of a sequence of moves, encoded as a word. In its current form, it only checks a sequence consisting of R's and U's. However it can be easily extended to 
#include all the transformations. Presumably we would not need primes because for example R^3 is the same thing as R', but we could have included that too.


def findOrderOfMoveSequence(wordSequence):
  Done=False
  n=0
  establishInitialPosition()
  while Done==False:
    for k in range(len(wordSequence)):
     if wordSequence[k]=="R":
       executeR()
     if wordSequence[k]=="U":
       executeU()

    n=n+1
    if checkInitial()==True:
      Done=True
      return n



####################################################################################################################
####################################################################################################################
############## THE MAIN PROGRAM STARTS HERE########################################################################




#Here we find all the elements of the group G which is generated by U^2 and R. The idea is to begin with all words that are made of the symbols U^2 and R and find 
#the distinct ones that form the group G. If two such words give the same cube configuration, then we stipulate them to be equal. We try to list each element of G
#as a word in the elements R and U^2 in the most economical way. For example RU^2U^2R is the same thing as RR and the latter would be the preferred way of listing
#this element.

#The idea is to start with the empty word and keep adding U^2 or R to it in all possible ways until all the elements of the group are found.






# The variable noChange carries the number of words in U^2 and R that have been considered without having encountered an essentially new element. When noChange crosses 2000, then we assume that we have 
#listed all the elements of the group, something that is verified implicitly later.

noChange=0

###################################################################################################################







# The list group holds the cube configurations that are imposed by the elements of the group

group=[]

####################################################################################################################





# The list groupDescription holds the descriptions of the elements of the group as words in the U^2 and R

groupDescription=[]

###################################################################################################################









# The list groupOrder holds the order of the elements of the group

groupOrder=[]

###################################################################################################################






print("This program will explore the group of transformations")
print("generated by U^2 and R. This group will be denoted by G.")
print("...................................")






#At this point the cube has its initial configuration. This is turned into an element: the identity element of the group G

word=positionToWord()
group.append(word)
groupDescription.append("")

#######################################################################################################################





print("We will now determine the elements of the group G.")
print("...................................")










# We now find all the elements of the group by trying a tree of 2^30 possible words obtained by appending either R or U^2 at the end of the elements that we have at each stage.
# The number of 30 iterations of the process was chosen arbitrarily through experimentation


for i in range(30):
  for word in group:
    wordInMaking=groupDescription[group.index(word)]+"UU"
    wordToPosition(word)
    executeU()
    executeU()
    newWord=positionToWord()
    if newWord in group:
      noChange=noChange+1
      #print(str(len(group))+"--"+str(noChange))
      if noChange>2000:
        break
    else:
      noChange=0
      group.append(newWord)
      groupDescription.append(wordInMaking)
      #print(str(len(group))+"--0")
    wordToPosition(word)
    wordInMaking=groupDescription[group.index(word)]+"R"

    executeR()
    newWord=positionToWord()
    if newWord in group:
      noChange=noChange+1
      #print(str(len(group))+"--"+str(noChange))
      if noChange>2000:
        break
    else:
      noChange=0
      group.append(newWord)
      groupDescription.append(wordInMaking)
      #print(str(len(group))+"--0")


#############################################################################################################################




print("The elements of the group have been determined")
print("...................................")








#We now determine the orders of the elements of the group G.

for wordDescription in groupDescription:
  groupOrder.append(findOrderOfMoveSequence(wordDescription))

#############################################################################################################################













print("The orders of the elements of G have been computed.")
print("...................................")
print("Here are the orders that we found:")







#we now give the amounts of elements of G that have a given order

for i in range(1,31):
  s=groupOrder.count(i)
  if s>0:
    if s==1:
      print("1 element of order "+str(i))
    else:
      print(str(s)+" elements of order "+str(i))

###########################################################################################################################






#The following function implements the group operation in the group G.

def groupOperation(k,l):
  establishInitialPosition()
  elementWord=groupDescription[k]+groupDescription[l]
  for t in range(len(elementWord)):
    if elementWord[t]=="R":
      executeR()
    if elementWord[t]=="U":
      executeU()
  return group.index(positionToWord())


#########################################################################################################################





# The center of a group consists of those elements of the group that commute with every element of the group. The center of $G$ is trivial
# and the only reason to include this computation is the fact that it implicitly checks that the elements that we have singled out actually
# forma a group. The list groupCenter was constructed in order to hold the elements of the center of G.

groupCenter=[]

########################################################################################################################

print("We will now compute the center of G.")
print("...................................")




for i in range(len(group)):
  k=0
  for l in range(len(group)):
    if groupOperation(i,l)==groupOperation(l,i):
      k=k+1
    else:
      break
  if k==len(group):
    groupCenter.append(i)


######################################################################################################################




print("The number of elements of the center of G is: "+str(len(groupCenter)))
print("Thus the center of G is trivial.")
print("...................................")





#We will now turn to the element a=R^2U^2R^2U^2R^2U^2. It is the element 110 of the group G.

print("We will now single out the following element of G:")
print(groupDescription[110])
print("We will call this element a.")
print("...................................")

#################################################################################################################################






#We now compute the centralizer of a.

print("In particular we will compute its centralizer, i.e. the subgroup of G consisting of the elements of G that commute with it.")
print("...................................")

################################################################################################################################




centralizer110=[]

for l in range(len(group)):
  if groupOperation(110,l)==groupOperation(l,110):
    centralizer110.append(l)




print("We will denote this centralizer by H and it has "+str(len(centralizer110))+ " elements.")
print("...................................")


################################################################################################################################





# We now wish to find the coset space G/H of left cosets of H in G. We know that it will consist of 10 cosets, the first one being H itself.
# The data structure that will hold these cosets is a list of 10 lists each containing 1440 elements that reference the list positions of G.


cosetCentralizer110=[]
cosetCentralizer110.append(centralizer110)
for i in range(9):
  cosetCentralizer110.append([])


##################################################################################################################################


print("The cosets of H in G are being determined.")
print("...................................")


# The idea of finding the cosets is rather simple. Look at the cosets that we have so far and find an element of G that does not belong to any of them.
# Then the next coset will be the set of all products of that element with the elements of the H. We do this for the 8 intermediate cosets. The last
# coset consists simply of the elements of G that do not belong to any other coset. This whole process can be potentially improved.

for i in range(1,9):
  k=0
  l=0
  while True:
    for j in range(10):
      if k in cosetCentralizer110[j]:
        l=l+1
    if l==0:
      for m in range(len(cosetCentralizer110[0])):
        cosetCentralizer110[i].append(groupOperation(k,cosetCentralizer110[0][m]))
      break
    else:
      k=k+1
      l=0

for m in range(len(group)):
  l=0
  for i in range(9):
    if m in cosetCentralizer110[i]:
      l=l+1


  if l==0:
    cosetCentralizer110[9].append(m)

print("The cosets of the centralizer of element 110 have been determined")
print("...................................")






#################################################################################################################################












# We now wish to act with G on the set of cosets G/H by left multiplication. We single out all the elements of G that have a trivial action
# and we know that they will form a normal subgroup of G. We hold these elements in a list called normalSubgroup.

normalSubgroup=[]

#########################################################################################################################






















print("We now consider the action of G on G/H.")
print("In particular we single out the elements of G")
print("that act trivially on G/H.")
print("They form a normal subgroup of G that we denote by K.")
print("...................................")


k=0
for m in range(len(group)):
  l=0
  for i in range(10):
    if groupOperation(m,cosetCentralizer110[i][0]) not in cosetCentralizer110[i]:
      l=l+1
  if l==0:
    k=k+1
    normalSubgroup.append(m)

print("The elements of K have been found.")
print("We list them in terms of their original positions in the list of the group G:")

print(normalSubgroup)
print("...................................")

###################################################################################################################################














# We now compute the orders of the centralizers of the elements of K in an attempt to learn as much as possible about it.
# For example this process can potentially give us interesting subgroups of K.

print("We will now list the orders of the centralizers of the elements of K.")
print("...................................")

for i in range(len(normalSubgroup)):
  m=0
  for k in range(len(normalSubgroup)):
    if groupOperation(normalSubgroup[i],normalSubgroup[k])==groupOperation(normalSubgroup[k],normalSubgroup[i]):
      m=m+1
  print("The centralizer of "+str(normalSubgroup[i])+" has "+str(m)+" elements.")

print("...................................")


#################################################################################################################################






#We now list the orders of elements of K.

normalSubgroupOrder=[]

for i in range(len(normalSubgroup)):
  normalSubgroupOrder.append(groupOrder[normalSubgroup[i]])


print("Here are the orders of the elements of K.")

for i in range(1,7):
  s=normalSubgroupOrder.count(i)
  if s>0:
    if s==1:
      print("1 element of order "+str(i))
    else:
      print(str(s)+" elements of order "+str(i))


print("...................................")
print("These orders completely match the orders of the elements of S_5")
print("With a simple theoretical argument we can actually verify that K is isormorphic to S_5")
print("...................................")
print("This concludes our program.")
print("...................................")

    



  
    
  
    
  








  



